			case 0:/* child process, exec() */

				if(redir_out){ //redirection to output file
					dup2(fd, STDOUT_FILENO);
					close(fd);
				}
				else if(redir_in){ //redirection to input file
					dup2(fd, STDIN_FILENO);
					close(fd);
				}


				execvp(args[0], args);
				perror("execv");
