<p>Here's a reduced snippet:</p>

<pre><code>typedef float ftype;
struct Foo
{
    ftype v;

    Foo(): v(16.0f / 60.0f) {}
    ftype val() const {return v * 60.0f;}
};

void bar()
{
    Foo f;
    ftype v = f.val();
    if (v != f.val())
        printf("inequal");
}
</code></pre>

