        }
    
        public virtual void DoItVirtual1()
        {
          Console.WriteLine ("Base: DoItVirtual1");
        }
    
        public virtual void DoItVirtual2()
        {
          Console.WriteLine ("Base: DoItVirtual2");
        }    
    
    }
    
    public class Derived : Base
