4 bit alu using vhdl showing errorno function declarations for operator "+"-*/"

    library ieee;
    use ieee.std_logic_1164.all;
    use ieee.numeric_std.all;
     
    
    entity alu is
          
     generic ( constant N: natural := 1 );     
         
           port( a,b : in std_logic_vector(3 downto 0);
                 sel : in std_logic_vector(3 downto 0);
                 y : out std_logic_vector(3 downto 0);
                 x: out std_logic_vector(7 downto 0);
                 cout : out std_logic);
    end alu;
    
    
    architecture behavioral of alu is
    signal rslt : std_logic_vector(3 downto 0);
    signal tmp :  std_logic_vector(4 downto 0);
    begin
      
    
    process(a,b,sel)
    
    
    begin
    
    case sel is
     
            when "0000"=>
    
             rslt<= a + b;
             when "0001"=>
             rslt<= a - b;
              when "0010"=>
              x<= (unsigned(a)) * (unsigned(b));
              when "0011"=>
              x<=(unsigned(a)) / (unsigned(b));
              when "0100"=>
             rslt<=std_logic_vector(unsigned(a) sll N);
              when "0101"=>
             rslt<=std_logic_vector(unsigned(a) srl N);
             when "0110"=>
             rslt<=std_logic_vector(unsigned(a) rol N);
              when "0111"=>
             rslt<=std_logic_vector(unsigned(a) ror N);
              when "1000"=>
             rslt<= a and b;
              when "1001"=>
             rslt<= a or b;
               when "1010"=>
             rslt<= a xor b;
               when "1011"=>
             rslt<= a xnor b;
               when "1100"=>
             rslt<= a nand b;
               when "1101"=>
             rslt<= a nor b;
                when "1110"=>
                   if (a > b) then
                         rslt<= "0001";
                    else
