        int number= 0;
        int trynum = 0;
        while(uniq(number= (r.nextInt(9000) + 1000)));
        String targetStr = number +"";
        boolean game = true;
        Scanner input = new Scanner(System.in);
        do{
            System.out.println(number);
            int bulls = 0;
            int cows = 0;
