<pre><code>typedef std::queue&lt;int&gt; Queue;
int findNthUglyNumber(int n) {
    Queue twoQ, threeQ, fiveQ;
    twoQ.push(2);
    threeQ.push(3);
    fiveQ.push(5);
    int u, q;
    while (n) {
        u = getNextUglyNumber(twoQ, threeQ, fiveQ, &amp;q);
