        case 3:
            threeQ.push(u &lt;&lt; 2 - u);     /// u * 3
        case 5:
            fiveQ.push(u &lt;&lt; 2 + u);      /// u * 5
        }
        n--;
        std::cout &lt;&lt; u &lt;&lt; ' ';
    }
    return u;
}

int getNextUglyNumber(Queue &amp;twoQ, Queue &amp;threeQ, Queue &amp;fiveQ, int &amp;q) {
    int u = twoQ.front();
    *q = 2;
    if (threeQ.front() &lt; u) {
        u = threeQ.front();
        *q = 3;
    }
    if (fiveQ.front() &lt; u) {
        u = fiveQ.front();
        *q = 5;
    }
    switch (*q) {
    case 2:
        twoQ.pop();
        break;
    case 3:
        threeQ.pop();
        break;
    case 5:
        fiveQ.pop();
        break;
    }
    return u;
}
</code></pre>

