using namespace std;

double calculate_average(int test_values[], int&amp; size, int&amp; sum, double&amp; average) {
    int i;
    for (i = 0; i &lt; size; i++) {
        sum += test_values[i];
    };
    return average = sum / i;
    };

double var(int test_values[], int size, double average, double&amp; variance) {

    for (int j = 0; j &lt; size; j++) {
