<p>here's my authentication: </p>

<pre><code>export function loginUser(creds) {

const data = querystring.stringify({_username: creds.username, _password: creds.password});

let config = {
    method: 'POST',
    headers: { 'Content-Type':'application/x-www-form-urlencoded' },
    body: data
};

return dispatch =&gt; {
    // We dispatch requestLogin to kickoff the call to the API
    dispatch(requestLogin(creds));

    return fetch(BASE_URL+'/login_check', config)
        .then(response =&gt;
            response.json().then(user =&gt; ({ user, response }))
        ).then(({ user, response }) =&gt;  {
            if (!response.ok) {
                // If there was a problem, we want to
                // dispatch the error condition
                dispatch(loginError(user.message));
                return Promise.reject(user)
            } else {
                // If login was successful, set the token in local storage
                localStorage.setItem('id_token', user.token);
                let token = localStorage.getItem('id_token')
                console.log(token);
                // Dispatch the success action
                dispatch(receiveLogin(user));
            }
        }).catch(err =&gt; console.log("Error: ", err))
    }
}
</code></pre>

<p>and here's the <code>POST</code> request (I'm getting the <code>values</code> object from <code>redux-form</code>)</p>

