    class Solution {
    public List<List<Integer>> largeGroupPositions(String S) {
        //int k=0;
        List<Integer> l1 = new ArrayList<Integer>();
        List<List<Integer>> l2 = new ArrayList<List<Integer>>();
        int n = S.length();
        
        int count =1, i1=0, i2=0;
        for(int i=1; i<n; i++){
            if(S.charAt(i)==S.charAt(i-1)){
                count++;
                
            }else{
                i2 = i-1;
                if(count>=3){
                    l1.add(i1);
                    l1.add(i2);
                    l2.add(l1);
                  
                    
                }
                
                count =1;
                i1=i;
            }
        }
        
