fun &lt;T&gt; Observable&lt;T&gt;.toLiveData(backPressureStrategy: BackpressureStrategy) :  LiveData&lt;T&gt; {
    return LiveDataReactiveStreams.fromPublisher(this.toFlowable(backPressureStrategy))
}

fun &lt;T&gt; Single&lt;T&gt;.toLiveData() :  LiveData&lt;T&gt; {
