}

fun &lt;T&gt; Maybe&lt;T&gt;.toLiveData() :  LiveData&lt;T&gt; {
    return LiveDataReactiveStreams.fromPublisher(this.toFlowable())
}

fun &lt;T&gt; Completable.toLiveData() :  LiveData&lt;T&gt; {
