            {
                // fails
                $this->load->view('sign_up');
            }
            else
            {
                //insert the user registration details into database
                $data = array(
                    'name' => $this->input->post('name'),
                    'email' => $this->input->post('email'),
                    'password' => $this->input->post('password')
                );
                
                // insert form data into database
