                        redirect('Register/reg');
                    }
                }
                else
                {
                    // error
                    $this->session->set_flashdata('msg','<div class="alert alert-danger text-center">Oops! Error.  Please try again later!!!</div>');
                    redirect('Register/reg');
                }
            }
        }
        
        function verify($hash=NULL)
        {
            if ($this->Seller_model->verifyEmailID($hash))
            {
