<p>Here is my code:</p>

<pre><code>function configuration(comments, instances, connections)
{
    this.comments = comments;
    this.instances = instances;
    this.connections = connections;

    return this;
}

function instance(id, type)
{
    this.id = id;
    this.type = type;

    return this;
}

function connection(from, to)
{
    this.from = from;
    this.to = to;

    return this;
}

function from(id, property, index)
{
    this.id = id;
    this.property = property;
    this.index = index;

    return this;
}

function to(id, property, index)
{
    this.id = id;
    this.property = property;
    this.index = index;

    return this;
}


var comments = "this is a test comment";
var instances = [];
var connections = [];

connections.push(connection(from("34hvd","inputs", 0), to("dheb3", "outputs", 0)));
instances.push(instance("34vd", "tee"));
instances.push(instance("dheb2", "average"));

var config = configuration(comments, instances, connections);
JSON.stringify(config);
</code></pre>

<p>As you can see I am trying to stringify the configuration object which contains a comment (string), instances(array of instance objects), and connections (array of connection objects). </p>

