  Foo(size_t n){}
};

class Bar
{
public:
  Bar() = default;
  Bar(const Foo&lt;size_t&gt; &amp;A, bool a=true, bool b=true){};
};

int main()
{
  Bar A({1,2});
}
</code></pre>

